import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.CVt6dz2a.js";const p=JSON.parse('{"title":"EP.15 glTF 资产管线：200MB 模型瘦身记","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.15-gltf-pipeline.md","filePath":"comics/EP.15-gltf-pipeline.md","lastUpdated":1793881879000}'),d={name:"comics/EP.15-gltf-pipeline.md"};function l(i,e,n,c,s,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-15-gltf-资产管线-200mb-模型瘦身记" tabindex="-1">EP.15 glTF 资产管线：200MB 模型瘦身记 <a class="header-anchor" href="#ep-15-gltf-资产管线-200mb-模型瘦身记" aria-label="Permalink to &quot;EP.15 glTF 资产管线：200MB 模型瘦身记&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/15-gltf-pipeline/basics">15.1 基础入门：glTF 格式与 GLTFLoader</a> 延伸阅读：<a href="./../guide/15-gltf-pipeline/advanced">进阶篇</a> · <a href="./../guide/15-gltf-pipeline/practice">实战篇</a> 动手演示：<a href="./../public/demos/gltf/first-gltf.html">first-gltf 加载第一个 glTF 模型</a> · <a href="./../public/demos/gltf/draco-ktx2-compare.html">draco-ktx2-compare 压缩管线对比</a> · <a href="./../public/demos/gltf/model-viewer.html">model-viewer 模型展示页</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君兴冲冲接过美术给的模型——200MB！网页一打开进度条爬了半分钟，浏览器直接卡死。</td></tr><tr><td>② 揭秘</td><td>码叔摊开 glTF 的结构图：JSON 场景描述 + 几何 + 贴图 + 动画全打包；再祭出两件兵器——DRACO 压几何、KTX2 压贴图。</td></tr><tr><td>③ 实证</td><td>像素酱一条 <code>gltf-transform</code> 命令跑完，200MB 瘦到 5MB，页面秒开，骨骼动画照播不误。</td></tr><tr><td>④ 结案</td><td>码叔贴出坑点清单并总结：模型不是美术导完就结束了，管线才是资产的最后一公里。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-gltf-3d-界的-jpeg" tabindex="-1">① glTF：3D 界的 JPEG <a class="header-anchor" href="#_1-gltf-3d-界的-jpeg" aria-label="Permalink to &quot;① glTF：3D 界的 JPEG&quot;">​</a></h3><p>glTF 是 Khronos 制定的开放交换标准，一种格式装下整个模型：场景层级（nodes）、网格（meshes）、PBR 材质、骨骼与动画（skins/animations）。两种形态：</p><table tabindex="0"><thead><tr><th>形态</th><th>结构</th><th>适用</th></tr></thead><tbody><tr><td>.gltf</td><td>JSON 主文件 + 外部 .bin + 外部贴图</td><td>调试期，可读可改</td></tr><tr><td>.glb</td><td>单文件二进制全打包</td><td><strong>生产环境首选</strong>，不丢文件</td></tr></tbody></table><h3 id="_2-压缩两件兵器" tabindex="-1">② 压缩两件兵器 <a class="header-anchor" href="#_2-压缩两件兵器" aria-label="Permalink to &quot;② 压缩两件兵器&quot;">​</a></h3><ul><li><strong>DRACO（几何）</strong>：顶点量化 + 熵编码，几何体积减 40%~90%。加载端配 <code>DRACOLoader</code> + <code>setDecoderPath()</code>，解码器首次遇到压缩模型时才按需下载；</li><li><strong>KTX2/Basis（贴图）</strong>：转成 GPU 块压缩格式，文件更小的同时<strong>显存里也不解压</strong>，1024² 贴图显存从 5.6MB 降到约 0.7MB。加载端配 <code>KTX2Loader</code> + <code>setTranscoderPath()</code>，<strong>必须 <code>detectSupport(renderer)</code></strong>。</li></ul><p>实测（Soldier.glb）：原始 2.06MB → +DRACO 1.19MB → 再叠 WebP 贴图 0.80MB → 贴图换 KTX2 后约 0.5MB，累计 −75%。</p><h3 id="_3-动画照播-animationmixer" tabindex="-1">③ 动画照播：AnimationMixer <a class="header-anchor" href="#_3-动画照播-animationmixer" aria-label="Permalink to &quot;③ 动画照播：AnimationMixer&quot;">​</a></h3><p>压缩只动几何与贴图的字节排布，<code>gltf.animations</code> 里的骨骼动画片段完好无损。<code>AnimationMixer</code> + <code>clipAction(clip).play()</code> 即可播放；切换动作用 <code>next.reset().fadeIn(0.3).play()</code> 配 <code>current.fadeOut(0.3)</code> 交叉过渡；千万别忘每帧 <code>mixer.update(delta)</code>。</p><h3 id="_4-管线意识" tabindex="-1">④ 管线意识 <a class="header-anchor" href="#_4-管线意识" aria-label="Permalink to &quot;④ 管线意识&quot;">​</a></h3><p>从&quot;美术导出&quot;到&quot;网页秒开&quot;之间隔着一条资产管线：Blender 导出（.glb、应用变换、勾 Draco）→ gltf-transform/gltfpack 后处理（WebP/KTX2）→ 加载端装配解码器与 LoadingManager。任何一环缺失，用户看到的就是白屏或黑模型。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：模型加载出来全黑？</strong> glTF 全是 PBR 材质，没有 <code>scene.environment</code> 就没有可反射的内容；用 PMREMGenerator + RoomEnvironment 补上即可。</li><li><strong>Q：动画不播？</strong> 先打印 <code>gltf.animations</code> 看是不是空（导出没勾动画）；再查渲染循环里有没有每帧 <code>mixer.update(delta)</code>。</li><li><strong>Q：DRACO 报 decoder 404？</strong> <code>setDecoderPath</code> 指目录且结尾带 <code>/</code>，目录下要有 wrapper.js + decoder.js + decoder.wasm 三件套。</li><li><strong>Q：KTX2 贴图不显示？</strong> 九成是漏了 <code>ktx2Loader.detectSupport(renderer)</code>。</li><li><strong>Q：贴图 404 但本地好的？</strong> 贴图路径相对于 .gltf 文件，且 Linux 服务器区分大小写；换 .glb 单文件可绝育此问题。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>.gltf 与 .glb 有什么区别？生产环境推荐哪个，为什么？</li><li>DRACO 与 KTX2 分别压缩什么？KTX2 除了文件小还有什么收益？</li><li>切换骨骼动画时为什么要用 fadeIn/fadeOut 而不是直接 stop/play？</li></ol><details><summary>答案</summary><ol><li>.gltf 是 JSON 主文件 + 外部 .bin/贴图，多文件可读可改；.glb 把全部内容打包成单文件二进制。生产推荐 <strong>.glb</strong>：一个请求、不会漏传贴图、没有相对路径和大小写问题。</li><li>DRACO 压<strong>几何</strong>（顶点/法线/UV），KTX2 压<strong>贴图</strong>。KTX2 的额外收益是贴图在<strong>显存中保持块压缩格式</strong>不解压，显存占用降 4~8 倍，移动端收益尤其大。</li><li>直接 stop/play 会让姿态瞬间跳变（还可能闪回 T-Pose）；<code>reset().fadeIn(0.3).play()</code> 与 <code>fadeOut(0.3)</code> 让新旧动作权重在 0.3 秒内平滑交叉过渡，视觉上动作是&quot;渐变&quot;过去的。</li></ol></details>',20)])])}const f=t(d,[["render",l]]);export{p as __pageData,f as default};
